SELECT sync_upload.row_id, action, status, stage, sent, total, wait, attempts, error_kind, error_message, size, sync_upload.transfer_id, batch, round_error, progress, source, CASE WHEN batch IS NULL THEN NULL ELSE batch_progress END, outcome.kind, outcome.value FROM sync_upload LEFT JOIN outcome ON outcome.owner = 'transfer' AND outcome.id = sync_upload.transfer_id AND outcome.cycle_id = sync_upload.cycle_id WHERE sync_upload.model = ? AND sync_upload.row_id IN ({marks})
